// What Grok Voice gets back from get_hazards: the same plain-English facts the written summary uses
// (lib/summary/facts.mjs), not the raw /hazards JSON. Tested on real data, the raw JSON led Grok to read
// "west of longitude -121.9" aloud and to call change_since_early_f a temperature drop. Safe for the browser.

// Relative import (not "@/") so node test scripts can load this file too.
import { buildFacts } from "../summary/facts.mjs";

type HazardJson = { status?: string; action?: string; change_since_early_f?: number | null; early_years?: number[]; recent_years?: number[] };
type Report = { address?: string | null; in_king_county?: boolean; message?: string | null; hazards?: Record<string, HazardJson> | null };
type FactHazard = { key: string; status: string; text: string; action: string; unknown?: boolean; skip?: boolean };

const span = (years?: number[]) => (years?.length ? `${years[0]} to ${years[years.length - 1]}` : "");

// change_since_early_f compares this spot with a typical lowland spot, then vs now. It says nothing about
// whether summers overall got hotter, so the wording keeps that explicit.
function heatTrend(h?: HazardJson): string | undefined {
  const c = h?.change_since_early_f;
  if (h?.status !== "ok" || c == null || !h.early_years?.length || !h.recent_years?.length) return undefined;
  const r = Math.round(Math.abs(c));
  const change = r === 0 ? "about the same" : `about ${r}°F ${c > 0 ? "warmer" : "cooler"}`;
  return `Compared with a typical spot in lowland King County, this spot ran ${change} in ${span(h.recent_years)} than it did in ${span(h.early_years)}. ` +
    `This compares spots with each other; it does not say whether summers overall got hotter or cooler.`;
}

export function hazardsForVoice(report: unknown) {
  const r = report as Report | null;
  if (!r) return { error: "No address has been looked up yet." };
  if (!r.in_king_county) return { address: r.address, in_king_county: false, message: "This address is outside King County, Washington, so this report has no hazard data for it. Do not suggest King County services for it; suggest its own city or county instead." };
  const facts = buildFacts(r) as { hazards: FactHazard[]; caveats?: string[] };
  const hazards: Record<string, { status: string; finding: string; action: string; trend?: string }> = {};
  for (const h of facts.hazards) {
    hazards[h.key] = {
      status: h.status,
      finding: h.text.replace(/^[A-Za-z ]+: (UNKNOWN\. )?/, "").replace(/^./, (c) => c.toUpperCase()),
      action: h.action,
      ...(h.key === "heat" && heatTrend(r.hazards?.heat) ? { trend: heatTrend(r.hazards?.heat) } : {}),
    };
  }
  return { address: r.address, in_king_county: true, hazards, limitations: facts.caveats ?? [] };
}

// Runs Grok's get_hazards tool call. With an address it looks the place up anywhere in King County;
// without one it uses the report the page is showing (if any). Always resolves to something Grok can say.
export async function runGetHazards(
  argsJson: string,
  { fetchHazards, current }: { fetchHazards: (address: string) => Promise<Response>; current?: unknown },
) {
  let address = "";
  try {
    address = String((JSON.parse(argsJson || "{}") as { address?: unknown }).address ?? "").trim();
  } catch {}
  if (!address) {
    return current
      ? hazardsForVoice(current)
      : { error: "No address yet. Ask the user for a street address in King County, with the city." };
  }
  try {
    const res = await fetchHazards(address);
    if (res.ok) return hazardsForVoice(await res.json());
    if (res.status === 404 || res.status === 422)
      return { error: `Could not find "${address}". Ask the user for a full street address with the city, like "400 Broad St, Seattle".` };
    return { error: "The hazard lookup is not working right now. Tell the user to try again in a moment." };
  } catch {
    return { error: "The hazard lookup is not working right now. Tell the user to try again in a moment." };
  }
}
